UPDATE distributed_task_locks
SET is_locked = FALSE,
    lock_time = NULL,
    version = version + 1
WHERE task_key = #{taskKey}
  AND node_id = #{nodeId}

UPDATE distributed_task_locks
SET heartbeat_time = NOW(),
    version = version + 1
WHERE task_key = #{taskKey}
  AND node_id = #{nodeId}
  AND is_locked = 1
